namespace ScreenshotTranslationUiTester;
internal static class AiStorageText147
{
    private static readonly Dictionary<string,string[]> Values=new(StringComparer.Ordinal)
    {
        ["Section"]=["AI chat storage","AI 聊天存储","AI 聊天儲存","AI チャットの保存先","AI 채팅 저장소","Almacenamiento de chats de IA","Stockage des dialogues IA","KI-Chat-Speicher","Хранение чатов ИИ"],
        ["Root"]=["AI chat folder","AI 聊天目录","AI 聊天目錄","AI チャットのフォルダー","AI 채팅 폴더","Carpeta de chats de IA","Dossier des dialogues IA","KI-Chat-Ordner","Папка чатов ИИ"],
        ["Tasks"]=["Conversations","对话记录","對話記錄","会話履歴","대화 기록","Conversaciones","Conversations","Gespräche","История диалогов"],
        ["Conversations"]=["Attachments and activity","附件与执行记录","附件與執行記錄","添付ファイルと実行履歴","첨부 파일 및 실행 기록","Adjuntos y actividad","Pièces jointes et activité","Anhänge und Ausführung","Вложения и действия"],
        ["Projects"]=["Default projects","默认项目","預設專案","既定のプロジェクト","기본 프로젝트","Proyectos predeterminados","Projets par défaut","Standardprojekte","Проекты по умолчанию"],
        ["Harness"]=["Assistant runtime data","助手运行资料","助手執行資料","アシスタントの実行データ","도우미 실행 데이터","Datos de ejecución del asistente","Données d’exécution de l’assistant","Laufzeitdaten der Assistenten","Данные работы помощников"],
        ["Open"]=["Open folder","打开目录","開啟目錄","開く","폴더 열기","Abrir carpeta","Ouvrir","Ordner öffnen","Открыть папку"],
        ["ChangeRoot"]=["Change location…","更改位置…","變更位置…","場所を変更…","위치 변경…","Cambiar ubicación…","Changer l’emplacement…","Speicherort ändern…","Изменить расположение…"],
        ["LocateRoot"]=["Locate existing folder…","定位已有目录…","定位現有目錄…","既存フォルダーを指定…","기존 폴더 찾기…","Localizar carpeta existente…","Retrouver le dossier existant…","Vorhandenen Ordner suchen…","Найти существующую папку…"],
        ["LocateHelp"]=["Select the existing AI chat data folder. An empty folder cannot replace missing history.","请选择原有的 AI 聊天资料目录，不能用空目录替代丢失的记录。","請選擇原有的 AI 聊天資料目錄，不能以空目錄取代遺失的記錄。","既存の AI チャットデータのフォルダーを選んでください。空のフォルダーでは失われた履歴を置き換えられません。","기존 AI 채팅 데이터 폴더를 선택하세요. 빈 폴더로 누락된 기록을 대체할 수 없습니다.","Selecciona la carpeta existente de chats de IA. Una carpeta vacía no puede sustituir el historial perdido.","Sélectionnez le dossier existant des dialogues IA. Un dossier vide ne peut pas remplacer un historique manquant.","Vorhandenen KI-Chat-Datenordner wählen. Ein leerer Ordner kann fehlenden Verlauf nicht ersetzen.","Выберите существующую папку данных чатов ИИ. Пустая папка не заменяет пропавшую историю."],
        ["Located"]=["Existing AI chat data located. You can reopen AI tools.","已定位原有 AI 聊天资料，可以重新打开 AI 工具。","已定位原有 AI 聊天資料，可以重新開啟 AI 工具。","既存の AI チャットデータを確認しました。AI ツールを開き直せます。","기존 AI 채팅 데이터를 찾았습니다. AI 도구를 다시 열 수 있습니다.","Se localizaron los datos existentes. Puedes volver a abrir las herramientas de IA.","Les données existantes ont été retrouvées. Vous pouvez rouvrir les outils IA.","Vorhandene KI-Chat-Daten gefunden. Die KI-Werkzeuge können erneut geöffnet werden.","Существующие данные чатов ИИ найдены. Можно снова открыть инструменты ИИ."],
        ["ChooseRoot"]=["Choose an empty folder for all AI chat data","为全部 AI 聊天资料选择一个空目录","為全部 AI 聊天資料選擇空目錄","AI チャットの全データ用に空のフォルダーを選択","모든 AI 채팅 데이터를 위한 빈 폴더 선택","Elige una carpeta vacía para los datos de chats de IA","Choisissez un dossier vide pour les données des dialogues IA","Leeren Ordner für alle KI-Chat-Daten wählen","Выберите пустую папку для данных чатов ИИ"],
        ["DefaultHelp"]=["The default location is inside the application folder. A location change takes effect after copying and verification at the next start; this session keeps using the current location.","默认位于软件文件夹内。更改位置后，下次启动时复制并校验；本次仍使用当前目录。","預設位於軟體資料夾內。變更位置後，下次啟動時複製並核對；本次仍使用目前目錄。","既定ではアプリのフォルダー内に保存します。変更は次回起動時のコピーと検証後に反映され、今回は現在の場所を使います。","기본 위치는 프로그램 폴더 안입니다. 위치 변경은 다음 시작 시 복사와 검증 후 적용되며, 현재는 기존 위치를 사용합니다.","La ubicación predeterminada está dentro de la carpeta de la aplicación. El cambio se aplica tras copiar y verificar al iniciar de nuevo; esta sesión usa la ubicación actual.","L’emplacement par défaut se trouve dans le dossier de l’application. Le changement s’applique après copie et vérification au prochain démarrage ; cette session utilise l’emplacement actuel.","Der Standardspeicherort liegt im Programmordner. Änderungen gelten nach Kopieren und Prüfen beim nächsten Start; diese Sitzung nutzt den bisherigen Ort.","По умолчанию данные находятся в папке программы. Новое расположение применяется после копирования и проверки при следующем запуске; сейчас используется прежнее."],
        ["GeneralDataHelp"]=["Translation settings, the game library, images, screenshot history, translation caches and logs are stored here. Changing this folder does not move the separate AI chat folder below.","这里保存翻译设置、游戏库、图片、截图历史、译文缓存及日志。更改此目录不会移动下方独立的 AI 聊天目录。","這裡儲存翻譯設定、遊戲庫、圖片、截圖歷史、譯文快取及日誌。變更此目錄不會移動下方獨立的 AI 聊天目錄。","翻訳設定、ゲームライブラリ、画像、スクリーンショット履歴、翻訳キャッシュ、ログを保存します。変更しても下記の独立した AI チャットフォルダーは移動しません。","번역 설정, 게임 라이브러리, 이미지, 스크린샷 기록, 번역 캐시와 로그를 저장합니다. 이 위치를 변경해도 아래의 별도 AI 채팅 폴더는 이동하지 않습니다.","Aquí se guardan los ajustes de traducción, biblioteca, imágenes, historial de capturas, cachés y registros. Cambiar esta carpeta no mueve la carpeta independiente de chats de IA indicada abajo.","Ce dossier contient les réglages de traduction, la bibliothèque, les images, les captures, les caches et les journaux. Le changer ne déplace pas le dossier IA indépendant ci-dessous.","Hier liegen Übersetzungseinstellungen, Spielebibliothek, Bilder, Screenshotverlauf, Übersetzungscaches und Protokolle. Eine Änderung verschiebt nicht den separaten KI-Chat-Ordner darunter.","Здесь хранятся настройки перевода, библиотека игр, изображения, история снимков, кэши переводов и журналы. Смена этой папки не перемещает отдельную папку чатов ИИ ниже."],
        ["RetentionHelp"]=["Conversations, attachments and activity records are saved data, not temporary caches. Assistant runtime data also includes the assistants’ own sessions and caches.","对话、附件和执行记录是保存的资料，不是临时缓存。助手运行资料还包含助手自己的会话与缓存。","對話、附件與執行記錄是儲存的資料，不是暫存快取。助手執行資料也包含助手本身的會話與快取。","会話、添付ファイル、実行履歴は保存データであり、一時キャッシュではありません。実行データにはアシスタント自身のセッションとキャッシュも含まれます。","대화, 첨부 파일 및 실행 기록은 임시 캐시가 아닌 저장 자료입니다. 실행 데이터에는 도우미 자체 세션과 캐시도 포함됩니다.","Las conversaciones, adjuntos y actividades son datos guardados, no cachés temporales. Los datos de ejecución también incluyen sesiones y cachés de los asistentes.","Les conversations, pièces jointes et activités sont des données enregistrées, pas des caches temporaires. Les données d’exécution incluent aussi les sessions et caches des assistants.","Gespräche, Anhänge und Ausführungsprotokolle sind gespeicherte Daten, keine temporären Caches. Die Laufzeitdaten enthalten auch eigene Sitzungen und Caches der Assistenten.","Диалоги, вложения и записи действий — сохранённые данные, а не временный кэш. Данные работы также включают собственные сеансы и кэши помощников."],
        ["ExternalHelp"]=["Project folders selected separately in a conversation stay in their original locations. Their files are not moved by this setting.","在对话中单独选择的外部项目仍保留在原位置，不随这里的目录迁移。","在對話中另行選擇的外部專案仍保留原位置，不隨此目錄遷移。","会話で個別に選んだ外部プロジェクトは元の場所に残り、この設定では移動しません。","대화에서 따로 선택한 외부 프로젝트는 원래 위치에 유지되며 이 설정으로 이동하지 않습니다.","Los proyectos elegidos por separado en una conversación permanecen en su ubicación original; este ajuste no los mueve.","Les projets choisis séparément dans une conversation restent à leur emplacement d’origine ; ce réglage ne les déplace pas.","In einem Gespräch separat gewählte externe Projekte bleiben an ihrem bisherigen Ort und werden hiermit nicht verschoben.","Внешние проекты, выбранные отдельно в диалоге, остаются на прежнем месте и этим параметром не перемещаются."],
        ["Pending"]=["Pending location: it will be copied and verified at the next start. The original folder is retained. If a new assistant session is needed, it continues with the saved conversation context.","下次启动时复制并校验到以下位置，原目录保留。若需要新的助手会话，会接续保留的聊天上下文。","下次啟動時複製並核對至下列位置，原目錄保留。若需新的助手會話，將接續保留的聊天內容。","次回起動時に以下へコピーして検証し、元のフォルダーは保持します。新しいアシスタントセッションが必要な場合も保存済みの会話内容を引き継ぎます。","다음 시작 시 아래 위치로 복사하고 검증하며 원본 폴더는 유지합니다. 새 도우미 세션이 필요하면 저장된 대화 맥락을 이어갑니다.","Se copiará y verificará en la siguiente ubicación al reiniciar, conservando la carpeta original. Si hace falta una nueva sesión, continuará con el contexto guardado.","Au prochain démarrage, les données seront copiées et vérifiées ici, en conservant le dossier d’origine. Si une nouvelle session est nécessaire, elle reprend le contexte enregistré.","Beim nächsten Start werden die Daten hierhin kopiert und geprüft; der alte Ordner bleibt erhalten. Eine nötige neue Sitzung übernimmt den gespeicherten Gesprächskontext.","При следующем запуске данные будут скопированы и проверены по этому пути; исходная папка останется. При необходимости новый сеанс продолжится с сохранённым контекстом."],
        ["Isolated"]=["This isolated test uses its own data folder; the normal AI chat location cannot be changed here.","当前是隔离测试数据目录，不能在此更改正式 AI 聊天位置。","目前使用隔離測試資料目錄，無法在此變更正式 AI 聊天位置。","現在は独立したテスト用データです。通常の AI チャット保存先はここでは変更できません。","현재는 격리된 테스트 데이터 폴더이므로 일반 AI 채팅 위치를 변경할 수 없습니다.","Esta prueba aislada usa su propia carpeta; aquí no se cambia la ubicación normal de chats de IA.","Ce test isolé utilise son propre dossier ; l’emplacement normal des dialogues IA ne peut pas être modifié ici.","Dieser isolierte Test nutzt eigene Daten; der normale KI-Chat-Speicherort lässt sich hier nicht ändern.","Это изолированные тестовые данные; обычное расположение чатов ИИ здесь изменить нельзя."],
        ["ai_storage_invalid"]=["Choose a valid empty folder outside the current AI and application data folders.","请选择有效的空目录，并避开当前 AI 目录和软件数据目录。","請選擇有效的空目錄，避開目前 AI 目錄與軟體資料目錄。","現在の AI データとアプリデータの外にある有効な空のフォルダーを選んでください。","현재 AI 및 프로그램 데이터 폴더 밖의 유효한 빈 폴더를 선택하세요.","Elige una carpeta vacía válida fuera de las carpetas actuales de IA y datos de la aplicación.","Choisissez un dossier vide valide hors des dossiers actuels de l’IA et de l’application.","Gültigen leeren Ordner außerhalb der bisherigen KI- und Programmdaten wählen.","Выберите допустимую пустую папку вне текущих папок ИИ и данных программы."],
        ["ai_storage_conflict"]=["The destination contains conflicting files. Choose another empty folder.","目标目录存在冲突文件，请选择其他空目录。","目標目錄有衝突檔案，請選擇其他空目錄。","移動先に競合するファイルがあります。別の空のフォルダーを選んでください。","대상 폴더에 충돌 파일이 있습니다. 다른 빈 폴더를 선택하세요.","El destino contiene archivos en conflicto. Elige otra carpeta vacía.","Le dossier cible contient des fichiers en conflit. Choisissez un autre dossier vide.","Im Zielordner gibt es Dateikonflikte. Anderen leeren Ordner wählen.","В папке назначения обнаружены конфликты файлов. Выберите другую пустую папку."],
        ["ai_storage_unavailable"]=["The AI storage folder is unavailable. Check its path and permissions.","AI 存储目录不可用，请检查路径和访问权限。","AI 儲存目錄無法使用，請檢查路徑與存取權限。","AI 保存先を利用できません。パスとアクセス権を確認してください。","AI 저장 폴더를 사용할 수 없습니다. 경로와 권한을 확인하세요.","La carpeta de IA no está disponible. Comprueba la ruta y los permisos.","Le dossier IA est inaccessible. Vérifiez le chemin et les autorisations.","KI-Speicherordner nicht verfügbar. Pfad und Zugriffsrechte prüfen.","Папка ИИ недоступна. Проверьте путь и разрешения."],
        ["ai_storage_changed"]=["AI data changed during verification. The location was not switched; try again after all AI activity has stopped.","核对时 AI 资料发生变化，未切换位置。请停止 AI 任务后重试。","核對時 AI 資料發生變化，未切換位置。請停止 AI 工作後重試。","検証中に AI データが変更されたため、保存先は切り替えていません。AI の処理を停止して再試行してください。","검증 중 AI 데이터가 변경되어 위치를 전환하지 않았습니다. AI 작업을 중지한 후 다시 시도하세요.","Los datos cambiaron durante la verificación. No se cambió la ubicación; detén las tareas de IA y reintenta.","Les données ont changé pendant la vérification. L’emplacement reste inchangé ; arrêtez les tâches IA et réessayez.","KI-Daten wurden während der Prüfung geändert. Speicherort unverändert; KI-Aufgaben stoppen und erneut versuchen.","Во время проверки данные ИИ изменились. Путь не переключён; остановите задачи ИИ и повторите."],
        ["ai_storage_isolated"]=["An isolated data launch cannot change the normal AI storage location.","隔离数据启动不能更改正式 AI 存储位置。","隔離資料啟動無法變更正式 AI 儲存位置。","独立したデータでの起動中は通常の AI 保存先を変更できません。","격리 데이터로 실행 중에는 일반 AI 저장 위치를 변경할 수 없습니다.","Un inicio con datos aislados no permite cambiar la ubicación normal de IA.","Un démarrage avec des données isolées ne peut pas modifier le stockage IA normal.","Ein Start mit isolierten Daten kann den normalen KI-Speicherort nicht ändern.","Запуск с изолированными данными не позволяет менять обычное хранилище ИИ."],
        ["ai_storage_pending"]=["An AI storage move is already pending. Restart Fusion to complete it before choosing another location.","已有待生效的 AI 目录迁移，请先重启 Fusion 完成迁移。","已有待生效的 AI 目錄遷移，請先重新啟動 Fusion 完成遷移。","AI 保存先の移動が保留中です。Fusion を再起動して完了してください。","AI 저장소 이동이 대기 중입니다. Fusion을 다시 시작해 완료하세요.","Ya hay una migración de IA pendiente. Reinicia Fusion para completarla.","Un déplacement du stockage IA est déjà prévu. Redémarrez Fusion pour le terminer.","Ein KI-Speicherumzug steht bereits aus. Fusion zum Abschließen neu starten.","Перенос хранилища ИИ уже ожидает выполнения. Перезапустите Fusion, чтобы завершить его."],
        ["ai_storage_busy"]=["The AI folder is in use. Close other Fusion windows using this folder, then try again.","AI 目录正在使用中，请退出使用该目录的其他 Fusion 窗口后重试。","AI 目錄使用中，請退出使用此目錄的其他 Fusion 視窗後重試。","AI フォルダーは使用中です。このフォルダーを使う他の Fusion ウィンドウを終了して再試行してください。","AI 폴더가 사용 중입니다. 이 폴더를 사용하는 다른 Fusion 창을 닫고 다시 시도하세요.","La carpeta de IA está en uso. Cierra las otras ventanas de Fusion que la usan y vuelve a intentarlo.","Le dossier IA est utilisé. Fermez les autres fenêtres Fusion qui l’utilisent, puis réessayez.","Der KI-Ordner wird verwendet. Andere Fusion-Fenster mit diesem Ordner schließen und erneut versuchen.","Папка ИИ используется. Закройте другие окна Fusion, использующие эту папку, и повторите."],
    };
    internal static IEnumerable<string> Keys=>Values.Keys;
    internal static string Text(string key)
    {
        if(!Values.TryGetValue(key,out var values))return AiToolsText.Text("ActionFailed");
        int index=UiLanguage.Current switch{ApplicationLanguage.SimplifiedChinese=>1,ApplicationLanguage.TraditionalChinese=>2,ApplicationLanguage.Japanese=>3,ApplicationLanguage.Korean=>4,ApplicationLanguage.Spanish=>5,ApplicationLanguage.French=>6,ApplicationLanguage.German=>7,ApplicationLanguage.Russian=>8,_=>0};return values[index];
    }
}
